/**
 * The frozen v1 index contract lookup — a v1-era wallet's display name read
 * straight from Gnosis. The fixture below is the REAL `getRecord` return for
 * the first v1 wallet this path was built for (name "大表哥"), captured from
 * the live contract, so the ABI walk (top offset → struct slot 4 → string
 * tail) is pinned against actual chain bytes.
 */
import { queryLegacyName, LEGACY_INDEX_CONTRACT, LEGACY_INDEX_CHAIN_ID } from '@/services/public-key-index';

jest.mock('react-native', () => ({}));
jest.mock('@react-native-async-storage/async-storage', () => ({
  __esModule: true,
  default: { getItem: jest.fn(), setItem: jest.fn(), removeItem: jest.fn() },
}));

const rpcCallMock = jest.fn();
jest.mock('@/services/rpc-adapter', () => ({
  rpcCall: (...args: unknown[]) => rpcCallMock(...args),
}));

const LIVE_RETURN = '';

describe('queryLegacyName (v1 contract eth_call)', () => {
  beforeEach(() => rpcCallMock.mockReset());

  it('decodes the on-chain record name from the live return shape', async () => {
    rpcCallMock.mockResolvedValueOnce({ result: LIVE_RETURN });
    const name = await queryLegacyName('getvela.app', '67173a3dd47bf093de62c5f3bcd550df792647fe');
    expect(name).toBe('大表哥');
    const [method, params, chainId] = rpcCallMock.mock.calls[0];
    expect(method).toBe('eth_call');
    expect(params[0].to).toBe(LEGACY_INDEX_CONTRACT);
    // getRecord(string,string) selector + two head offsets.
    expect(params[0].data.startsWith('0x')).toBe(true);
    expect(chainId).toBe(LEGACY_INDEX_CHAIN_ID);
  });

  it('a reverted call (no record) is null, never a throw', async () => {
    rpcCallMock.mockResolvedValueOnce({ error: { code: 3, message: 'execution reverted' } });
    await expect(queryLegacyName('getvela.app', 'deadbeef')).resolves.toBeNull();
  });

  it('an unreachable RPC is null, never a throw', async () => {
    rpcCallMock.mockRejectedValueOnce(new Error('all endpoints failed'));
    await expect(queryLegacyName('getvela.app', 'deadbeef')).resolves.toBeNull();
  });

  it('garbage return data is null, never a throw', async () => {
    rpcCallMock.mockResolvedValueOnce({ result: '0x1234' });
    await expect(queryLegacyName('getvela.app', 'deadbeef')).resolves.toBeNull();
  });
});
